INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 1, 1, 122601, 0, 1.5, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 0.029, 1, 101, 1, 160, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 2, 2, 122401, 1, 2.5, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 0.014, 3, 102, 0, 120, 111, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 3, 3, 122501, 0, 2.5, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 0.017, 2, 103, 0, 350, 105, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 4, 4, 107501, 1, 1.5, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 0.016, 3, 104, 0, 130, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 5, 5, 107601, 0, 2.5, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 0.014, 1, 105, 1, 160, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (120, 6, 6, 107801, 0, 3.5, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 0.029, 2, 106, 0, 255, 103, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (120, 7, 7, 110601, 0, 3.5, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 0.013, 1, 107, 1, 160, 103, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 8, 8, 110401, 0, 2.5, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 0.014, 2, 108, 0, 350, 103, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 9, 9, 110501, 1, 1.5, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 0.012, 3, 109, 0, 130, 100, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 10, 10, 115701, 0, 2.5, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 0.014, 1, 110, 1, 200, 103, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 11, 11, 113601, 0, 2.5, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 0.071, 2, 111, 0, 350, 103, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (120, 12, 12, 107901, 1, 1.5, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 0.014, 3, 112, 0, 130, 103, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 13, 13, 108001, 0, 1.5, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 0.022, 2, 113, 1, 200, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 14, 14, 110301, 0, 2.5, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 0.031, 1, 114, 1, 160, 108, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 15, 15, 107701, 1, 0.5, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 0.036, 1, 115, 0, 130, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 16, 16, 113101, 0, 3.5, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 0.048, 2, 116, 0, 350, 95, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 17, 17, 113301, 1, 1.5, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 0.043, 3, 117, 0, 130, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 18, 18, 113201, 1, 1.5, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 0.018, 2, 118, 0, 130, 95, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 19, 19, 117001, 0, 2.5, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 0.021, 2, 119, 1, 160, 108, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 20, 20, 113501, 0, 2.5, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 0.036, 1, 120, 0, 255, 105, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 21, 21, 113401, 0, 2.5, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 0.02, 3, 121, 0, 350, 105, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 22, 22, 110101, 1, 2.5, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 0.018, 1, 122, 0, 130, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 23, 23, 110001, 0, 3.5, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 0.03, 3, 123, 1, 160, 111, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 24, 24, 117201, 1, 1.5, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 0.027, 1, 124, 0, 130, 103, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 25, 25, 117301, 0, 3.5, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 0.02, 2, 125, 1, 160, 108, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 26, 26, 117401, 0, 2.5, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 0.04, 3, 126, 0, 350, 105, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 27, 27, 117101, 0, 3.5, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 0.009, 1, 127, 0, 350, 105, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (120, 28, 28, 122901, 0, 3.5, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 0.022, 1, 128, 0, 255, 105, 1);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (110, 29, 29, 122801, 1, 2.5, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 0.028, 3, 129, 0, 130, 105, 0);
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (105, 30, 30, 122701, 0, 3.5, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 0.023, 2, 130, 1, 130, 108, 0);
